$ErrorActionPreference = 'Stop'
if ($env:COMPUTERNAME -ine 'DC01') { throw 'Bu komut DC01 uzerinde calistirilmali.' }
$awPacked = @'

'@
$awInput = [IO.MemoryStream]::new([Convert]::FromBase64String($awPacked))
$awPlain = [IO.MemoryStream]::new()
$awZip = [IO.Compression.GZipStream]::new($awInput, [IO.Compression.CompressionMode]::Decompress)
try {
    $awZip.CopyTo($awPlain)
    $awBundle = [Text.Encoding]::UTF8.GetString($awPlain.ToArray()) | ConvertFrom-Json
} finally {
    $awZip.Dispose(); $awInput.Dispose(); $awPlain.Dispose()
}
$awCode = [string]$awBundle.skeleton
for ($i = 0; $i -lt $awBundle.parts.Count; $i++) {
    $awPart = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes([string]$awBundle.parts[$i]))
    $awCode = $awCode.Replace(('__AW_TRANSFER_PART_' + $i + '__'), $awPart)
}
$awHasher = [Security.Cryptography.SHA256]::Create()
try {
    $awHash = [BitConverter]::ToString($awHasher.ComputeHash([Text.Encoding]::UTF8.GetBytes($awCode))).Replace('-','').ToLowerInvariant()
} finally { $awHasher.Dispose() }
if ($awHash -ne '0a698cd597a70dc1e5b5016acfbbbcef4eb7256fcaba9e73591cf0e56a718484') {
    throw 'Icerik dogrulanamadi. Guncelleme yapilmadi.'
}
& ([scriptblock]::Create($awCode))
